var f: text;

procedure SaveToFile(p: TNode);
begin
  if p=nil then
  begin
    writeln(f,'');
    exit
  end;
  writeln(f,p.s);
  SaveToFile(p.left);
  SaveToFile(p.right);
end;

function LoadFromFile: TNode;
var
  s: string;
begin
  readln(f,s);
  if s='' then
  begin
    Result := nil;
    exit
  end;
  var p := new TNode(s);
  p.left := LoadFromFile;
  p.right := LoadFromFile;
  Result := p;
end;

