    root := new TNode('Dog')
  else
  begin
    reset(f);
    root := loadfromfile;
    close(f);
  end;

  p := root;
  while p.left<>nil do
  begin
    Print(p.s+'? (0 - No, 1 - Yes):');
    readln(x);
    if x=1 then 
      p := p.left
    else 
      p := p.right
  end;
  
  write('Is it '+p.s+'? (0 - No, 1 - Yes): ');
  readln(x);
  if x=1 then
    writeln('I guessed!')
  else
  begin
    write('I lost. What animal is it? ');
    readln(s);
    write('Enter a question that distinguishes this animal from '+p.s+': ');
    readln(q);
    p1 := new TNode(s);
    p2 := new TNode(p.s);
    p.s := q;
    p.left := p1;
    p.right := p2;
  end;
  
  Rewrite(f);
  SaveToFile(root);
  Close(f);
