// Algorithm for calculating polynomial value at point x using Horner's scheme

const n = 5;

begin
  var x := ReadReal('Enter value x:');
  Print($'Enter polynomial coefficients ({n + 1} pieces):');
  var a := ReadReal;
  var s := a;
  for var i := 1 to n do
