function IsCoordCorrect(x,y: integer): boolean;  
begin
  Result := (x in [1..WindowWidth]) and (y in [1..WindowHeight]);
end;
  
procedure MyGotoXY(x,y: integer);
begin
  if not IsCoordCorrect(x,y) then  
    exit;
  GotoXY(x,y);  
end;

procedure DrawSymbol(x,y: integer; c: char);
