uses System;

begin
  // Getting current date - calling static method
  var d1 := DateTime.Now; 
  Println(d1);
  
  // Date and time after one month
  var d2 := d1.AddMonths(1);
  Println(d2);

  // Date and time 12 hours earlier
  d2 := d1.AddHours(-12);
  Println(d2);

  // Creating date - calling object constructor (year, month, day)
  var d3 := new DateTime(2001, 1, 1);
  Println(d3);
  
  // Determining time passed since millennium start (date difference)
  var ts: TimeSpan := d1.Subtract(d3);

  // Time interval in days (result - real number)
  Println(ts.TotalDays);
  
  // Time interval in days, hours, minutes and seconds
  Println($'{ts.Days} {ts.Hours}:{ts.Minutes}:{ts.Seconds}');
end.




