type IntArr = array [1..Sz] of integer;

procedure PrintArr(const A: IntArr; n: integer);
begin
  for var i:=1 to n do
    Print(A[i]);
  Println;
end;

procedure TrySolve(n: integer; const B: IntArr; nb: integer);
var
  Subset: IntArr;
  space: integer;
  ns: integer;

  procedure TrySolve0(i: integer);
begin
    if space=0 then 
      PrintArr(Subset,ns)
    else if (space<0) or (i>nb) then 
      exit
    else
    begin
