// Task-based prime number checking
type
  Int = class
    N: int64;
    constructor(NN: int64);
    begin
      N := NN;
    end;
    function IsPrime: boolean;
    begin
      Result := True;
      for var i: int64 := 2 to round(sqrt(N)) do
        if N mod i = 0 then
        begin
          Result := False;
          exit;
        end;
    end;
  end;

type
  BTask = Task<boolean>;

begin
  var ss: array of int64 := (1265713689122381, 1265713689122461, 1265713689142451, 1265713689542501);
  var tb := new BTask[4];
  for var i := 0 to ss.Length - 1 do
    tb[i] := Task.Factory.StartNew((new Int(ss[i])).IsPrime);
  for var i := 0 to tb.Length - 1 do
    writeln(tb[i].Result);
  writeln(Milliseconds);  
end.

// Parallel for with thread-safe list
type
  ListSimple = class
    l := new List<int64>();
    procedure AddPrime(N: int64);
    begin
      var Result := True;
      for var i: int64 := 2 to round(sqrt(N)) do
        if N mod i = 0 then
        begin
          Result := False;
          break;
        end;
      lock l do 
        if Result then
          l.Add(N);
    end;
  end;

var hh := 1000;

begin
  var ls := new ListSimple;
  var ii: int64 := 1265713689181;
  Parallel.For(ii,ii+hh,ls.AddPrime);
  Println(ls.l.Count);
end.

