procedure Assert(cond: boolean; message: string; sourceFile: string; line: integer);
begin
  if (Environment.OSVersion.Platform = PlatformID.Unix) or (Environment.OSVersion.Platform = PlatformID.MacOSX) or IsWDE then
  begin
    if not IsWDE then
      System.Diagnostics.Debug.Assert(cond, 'File ' + sourceFile + ', line ' + line.ToString() + ': ' + message)
    else if not cond then
    begin
      var err := 'Assertion failure: ' + message + Environment.NewLine + 'File ' + sourceFile + ', line ' + line.ToString();
      Writeln(err);
      System.Threading.Thread.Sleep(500);
      raise new Exception();
    end;
  end
  else
    System.Diagnostics.Contracts.Contract.Assert(cond,'File '+sourceFile+', line '+line.ToString() + ': ' + message)
end;

