          ok := False; break;
        end;
        k += 1;
      end;
      if ok then
      begin
        bestLen := d;
        // since we iterate descending, the first valid d is the longest
        Result := bestLen; exit;
      end;
    end;
    d -= 1;
  end;
  Result := bestLen;
end;

