    begin
      left.next := current;
      left := left.next;
    end
    else
    begin
      right.next := current;
      right := right.next;
    end;
    current := current.next;
  end;
  
  left.next := rightHead.next;
  right.next := nil;
  Result := leftHead.next;
end;

