function IsPrime(N: integer): boolean;
begin
  if N < 2 then
  begin
    IsPrime := False;
    exit;
  end;
  if N = 2 then
  begin
    IsPrime := True;
    exit;
  end;
  if N mod 2 = 0 then
  begin
    IsPrime := False;
    exit;
  end;
  var Divisor := 3;
  while Divisor * Divisor <= N do
  begin
    if N mod Divisor = 0 then
    begin
      IsPrime := False;
      exit;
    end;
    Divisor += 2;
  end;
  IsPrime := True;
end;

