function ArePermutations(S1, S2: string): boolean;
begin
  if (S1 = nil) or (S2 = nil) then
  begin
    ArePermutations := False;
    exit;
  end;

  var N1 := NormalizeForPermutationCheck(S1);
  var N2 := NormalizeForPermutationCheck(S2);

  if N1.Length <> N2.Length then
  begin
    ArePermutations := False;
    exit;
  end;

  var A1 := N1.ToCharArray;
  var A2 := N2.ToCharArray;
  &Array.Sort(A1);
  &Array.Sort(A2);

  ArePermutations := new string(A1) = new string(A2);
end;

