function IsPrime(N: integer): boolean;
begin
  if N < 2 then
  begin
    IsPrime := False;
    exit;
  end;
  if N = 2 then
  begin
    IsPrime := True;
    exit;
  end;
  if N mod 2 = 0 then
  begin
    IsPrime := False;
    exit;
  end;
  var D := 3;
  while D * D <= N do
  begin
    if N mod D = 0 then
    begin
      IsPrime := False;
      exit;
    end;
    D += 2;
  end;
  IsPrime := True;
end;

