function CalculateSeriesSum(n: integer): real;
begin
  var sum := 1.0;
  for var i := 2 to n do
  begin
    var term := 1.0;
    for var j := 1 to i do
    begin
      term := term * (i / j);
    end;
    sum := sum + term;
  end;
  Result := sum;
end;

