function ReverseString(str: string): string;
begin
  var charArray := str.ToCharArray;
  &Array.Reverse(charArray);
  
  var reversedString := '';
  var previousChar := #0;
  
  foreach var c in charArray do
  begin
    if c <> previousChar then
    begin
      reversedString += c;
      previousChar := c;
    end;
  end;
  
  Result := reversedString.ToLower;
end;

