function ReverseInteger(number: integer): integer;
begin
  var reversedNumber := 0;
  var sign := 1;
  if number < 0 then
    sign := -1;
  number := Abs(number);
  
  while number > 0 do
  begin
    reversedNumber := reversedNumber * 10 + (number mod 10);
    number := number div 10;
  end;
  
  Result := reversedNumber * sign;
end;

