function TwinPrimeNumbers.IsPrimeLocal(number: integer): boolean;
begin
  if number <= 1 then
    Result := false
  else
  begin
    for var i := 2 to Trunc(Sqrt(number)) do
      if number mod i = 0 then
      begin
        Result := false;
        exit;
      end;
    Result := true;
  end;
end;

function TwinPrimeNumbers.FindTwinPrimes(n: integer): List<array of integer>;
begin
  var twinPrimes := new List<array of integer>();
  for var i := 3 to n - 2 do
    if IsPrimeLocal(i) and IsPrimeLocal(i + 2) then
      twinPrimes.Add(|i, i + 2|);
  Result := twinPrimes;
end;

function TwinPrimeNumbers.CalculateSum(twinPrimes: List<array of integer>): integer;
begin
  var sum := 0;
  foreach var twinPrime in twinPrimes do
    sum += twinPrime[0] + twinPrime[1];
  Result := sum;
end;

