  tokenSource := new CancellationTokenSource();
  Task.Run(GenerateWelcomeMessage, tokenSource.Token);
end;

procedure MainForm.MainForm_FormClosing(sender: object; e: FormClosingEventArgs);
begin
  tokenSource.Cancel();
  SaveCustomizedMessages();
