function IsPrime(num: integer): boolean;
begin
  if num < 2 then
    exit(False);
    
  for var i := 2 to &Round(Sqrt(num)) do
    if num mod i = 0 then
      exit(False);
      
  Result := True;
end;

function CalculatePrimeSum(n: integer): integer;
begin
  if n <= 1 then
    exit(0);
    
  if IsPrime(n) then
    Result := n + CalculatePrimeSum(n - 1)
  else
    Result := CalculatePrimeSum(n - 1);
end;

function GetPositiveIntegerInput(): integer;
