function IsPrime(number: integer): boolean;
begin
  if number < 2 then
    exit(False);
    
  for var i := 2 to &Round(Sqrt(number)) do
    if number mod i = 0 then
      exit(False);
      
  Result := True;
end;

function CalculatePrimeProduct(): real;
begin
  var count := 0;
  var product := System.Numerics.BigInteger.One;
  var num := 2;
  
  while count < 500 do
  begin
    if IsPrime(num) then
    begin
      product := product * num;
      count += 1;
    end;
    num += 1;
  end;
  
  var productDouble := real(product);
  Result := Sqrt(productDouble);
end;

begin
  for var i := 1 to 10 do
  begin
    var result := CalculatePrimeProduct();
    Println($'The square root of the product of the first 500 prime numbers is: {result}');
  end;
end.




