procedure GenerateCombinationsHelper(arr: array of integer; 
                                     var combinations: List<List<integer>>; 
                                     current: List<integer>; 
                                     n, start: integer);
begin
  if n = 0 then
  begin
    combinations.Add(new List<integer>(current));
    exit;
  end;
  
  for var i := start to arr.Length - 1 do
  begin
    if (i > start) and (arr[i] = arr[i - 1]) then
      continue;
      
    current.Add(arr[i]);
    GenerateCombinationsHelper(arr, combinations, current, n - 1, i + 1);
    current.RemoveAt(current.Count - 1);
  end;
end;

