begin
  var random := new System.Random;

  for var i := arr.Length - 1 downto 1 do
  begin
    var randomIndex := random.Next(i + 1);

    var temp := arr[i];
    arr[i] := arr[randomIndex];
    arr[randomIndex] := temp;
  end;
end;

