function CalculateArea(radius: real): string;
begin
  if radius < 0 then
    Result := 'Error: Negative radius value is not allowed.'
  else if radius > System.Double.MaxValue / (Pi * Pi) then
    Result := 'Error: Result exceeds maximum value.'
  else if radius = 0 then
    Result := '0'
  else
  begin
    var area := Round(Pi * radius * radius, 2);
    Result := area.ToString;
  end;
end;

