procedure ReverseArray(var arr: array of integer);
begin
  var start := 0;
  var &end := arr.Length - 1;

  while start < &end do
  begin
    var temp := arr[start];
    arr[start] := arr[&end];
    arr[&end] := temp;

    start += 1;
    &end -= 1;
  end;
end;

begin
  var numbers := Arr(1, 2, 3, 4);
  
  ReverseArray(numbers);
  
  Println('Reversed array:');
  foreach var number in numbers do
