    Println('Both the text and pattern must be provided.');
    exit;
  end;

  inputText := LowerCase(inputText);
  searchPattern := LowerCase(searchPattern);

  var occurrences := CountOccurrences(inputText, searchPattern);
  Println('Number of occurrences: ', occurrences);
end.




