function IntegerToString(value: int64): string;
begin
  if value = 0 then
  begin
    Result := '0';
    exit;
  end;

  var resultStr := '';
  while value > 0 do
  begin
    var digit := value mod 10;
    resultStr := Chr(digit + Ord('0')) + resultStr;
    value := value div 10;
  end;

  Result := resultStr;
end;

function DecimalToString(value: real): string;
begin
  var resultStr := '';
  var precision := 15;

  for var i := 1 to precision do
  begin
    value *= 10;
    var digit := Trunc(value);
    resultStr += Chr(digit + Ord('0'));
    value -= digit;
  end;

  Result := resultStr;
end;

function DoubleToString(value: real): string;
begin
  var isNegative := value < 0;
  if isNegative then
    value := -value;

  var integerValue := Trunc(value);
  var decimalValue := value - integerValue;

  var integerPart := IntegerToString(integerValue);
  var decimalPart := DecimalToString(decimalValue);

  if isNegative then
    Result := '-' + integerPart + '.' + decimalPart
  else
    Result := integerPart + '.' + decimalPart;
end;

begin
  var value := 7.75;
  var stringValue := DoubleToString(value);
  Println(stringValue);
end.




