function ConvertNumberToWords(number: int64): string;
begin
  if number = 0 then
  begin
    Result := 'Zero';
    exit;
  end;

  var words := '';
  var index := 0;

  while number > 0 do
  begin
    if number mod 1000 <> 0 then
      words := ConvertHundredsToWords(number mod 1000) + thousands[index] + ' ' + words;

    number := number div 1000;
    index += 1;
  end;

  Result := words.Trim;
end;

function ConvertHundredsToWords(number: integer): string;
begin
  var words := '';

  if number mod 100 < 20 then
  begin
    words := ones[number mod 100];
    number := number div 100;
  end
  else
  begin
    words := ones[number mod 10];
    number := number div 10;

    words := tens[number mod 10] + ' ' + words;
    number := number div 10;
  end;

  if number <> 0 then
    Result := ones[number] + ' Hundred ' + words
  else
    Result := words;
end;

