begin
  var fibonacciPrimes := new List<integer>;
  var a := 0;
  var b := 1;
  var c := 0;
  
  while c <= limit do
  begin
    if IsPrime(c) then
      fibonacciPrimes.Add(c);
    c := a + b;
    a := b;
    b := c;
  end;
  
