function ConvertToHex(value: int64): string;
begin
  var hexChars := '0123456789ABCDEF'.ToCharArray;
  var hex := new char[16];
  
  for var i := 0 to hex.Length - 1 do
  begin
    hex[hex.Length - 1 - i] := hexChars[value and $F];
    value := value shr 4;
  end;
  
  Result := new string(hex);
end;

