function CalculateFibonacci(n: integer): int64;
begin
  if n <= 0 then
    raise new System.ArgumentException('n must be a positive integer');
  
  if n <= 2 then
    Result := 1
  else
  begin
    var prev1: int64 := 1;
    var prev2: int64 := 1;
    var current: int64 := 0;
    
    for var i := 3 to n do
    begin
      current := prev1 + prev2;
      prev2 := prev1;
      prev1 := current;
    end;
    
    Result := current;
  end;
end;

begin
  Write('Enter the value of n: ');
  var n := ReadInteger;
  
  var result := CalculateFibonacci(n);
  Println($'The {n}th Fibonacci number is: {result}');
end.




