procedure GenerateCombinations<T>(arr: array of T; n: integer; current: List<T>; var combinations: List<List<T>>);
begin
  if current.Count = n then
  begin
    combinations.Add(current.ToList);
    exit;
  end;
  
  for var i := 0 to arr.Length - 1 do
  begin
    current.Add(arr[i]);
    GenerateCombinations(arr, n, current, combinations);
    current.RemoveAt(current.Count - 1);
  end;
end;

function GetCombinations<T>(arr: array of T; n: integer): List<List<T>>;
begin
  var combinations := new List<List<T>>;
  GenerateCombinations(arr, n, new List<T>, combinations);
  Result := combinations.OrderBy(c -> string.Join('', c)).ToList;
end;

