function IsPrime(number: int64): boolean;
begin
  // Check if number is less than 2
  if number < 2 then
    exit(false);

  // Check if number is divisible by any number from 2 to the square root of the number
  var sqrtValue := round(sqrt(number));
  for var i: int64 := 2 to sqrtValue do
  begin
    if number mod i = 0 then
      exit(false);
  end;

  Result := true;
end;

