function MultiplyByDigitSumAndFactorial(number: decimal): (decimal, integer);
begin
  // Calculate the sum of the digits
  var digitSum := 0;
  var numberString := number.ToString;
  foreach var c in numberString do
  begin
    if char.IsDigit(c) then
    begin
      digitSum += integer.Parse(c.ToString);
    end;
  end;

  // Calculate the factorial of the number of digits
  var numberOfDigits := numberString.Replace('.', '').Length;
  var factorial := CalculateFactorial(numberOfDigits);

  // Multiply the number by the sum of digits and the factorial
  var result1 := number * digitSum;
  var result2 := digitSum * factorial;
  
  Result := (result1, result2);
end;

begin
  var number := decimal(123.45);
  var (result1, result2) := MultiplyByDigitSumAndFactorial(number);
