    end;

    function CalculateSumOfEvenNumbers: integer;
    begin
      Result := numbers.Where(n -> n mod 2 = 0).Sum;
    end;

    function CalculateSumOfOddNumbers: integer;
    begin
      Result := numbers.Where(n -> n mod 2 <> 0).Sum;
    end;

    function CalculateSumOfUniqueNumbers: integer;
    begin
      Result := numbers.Distinct.Sum;
    end;

    function CalculateProduct: int64;
    begin
      if numbers.Count = 0 then
      begin
        raise new System.InvalidOperationException('No numbers entered.');
      end;

      Result := numbers.Aggregate(int64(1), (current, number) -> current * number);
    end;

    function CountPrimeNumbers: integer;
    begin
      if numbers.Count = 0 then
      begin
        raise new System.InvalidOperationException('No numbers entered.');
      end;

      Result := numbers.Count(IsPrime);
    end;
  end;

