    studentAge: integer;
    
    function GenerateUniqueId: integer;
    begin
      counter += 1;
      Result := counter;
    end;
    
  public
    constructor(newName: string; newAge: integer);
    begin
      studentId := GenerateUniqueId;
      UpdateName(newName);
      UpdateAge(newAge);
    end;
    
    property Id: integer read studentId;
    property Name: string read studentName;
    property Age: integer read studentAge;
    
    procedure UpdateName(newName: string);
    begin
      if newName.Length <= 50 then
      begin
        studentName := newName;
      end
      else
      begin
        Println('Name exceeds 50 characters.');
      end;
    end;
    
    procedure UpdateAge(newAge: integer);
    begin
      if (newAge >= 18) and (newAge <= 30) then
      begin
        studentAge := newAge;
      end
      else
      begin
        Println('Invalid age. Age must be between 18 and 30.');
      end;
    end;
    
    function CalculateAverageGrade(grades: List<integer>): real;
    begin
      if grades.Count > 100 then
      begin
        Println('Number of grades exceeds 100.');
        exit(0);
      end;
      
      var sum := 0;
      foreach var grade in grades do
      begin
        if (grade < 0) or (grade > 100) then
        begin
          Println('Invalid grade. Grades must be between 0 and 100.');
          exit(0);
        end;
        sum += grade;
      end;
      
      Result := sum / grades.Count;
    end;
    
    function HasPassedAllCourses(grades: List<integer>; passMarkPercentage: real): boolean;
    begin
      var averageGrade := CalculateAverageGrade(grades);
      var passMark := passMarkPercentage * 100;
      
      Result := averageGrade >= passMark;
    end;
  end;

