procedure ReverseString(var str: array of char);
begin
  var start := 0;
  var ends := str.Length - 1;

  while start < ends do
  begin
    var temp := str[start];
    str[start] := str[ends];
    str[ends] := temp;

    start += 1;
    ends -= 1;
  end;
end;

