function SqrtBinarySearch(x: integer): integer;
begin
  if (x = 0) or (x = 1) then
  begin
    Result := x;
    exit;
  end;
  
  var start := 1;
  var &end := x;
  var ans := 0;
  
  while start <= &end do
  begin
    var mid := (start + &end) div 2;
    
    if mid * mid = x then
    begin
      Result := mid;
      exit;
    end;
    
    if mid * mid < x then
    begin
      start := mid + 1;
      ans := mid;
    end
    else
      &end := mid - 1;
  end;
  
  Result := ans;
end;

