  var diff := A[1] - A[0];
  var count := 2;
  
  for var i := 2 to A.Length - 1 do
  begin
    if A[i] - A[i-1] = diff then
    begin
      count += 1;
      if count >= 3 then
      begin
        Result := True;
        exit;
      end;
    end
    else
    begin
      if count >= 3 then
      begin
        Result := True;
        exit;
      end;
      diff := A[i] - A[i-1];
      count := 2;
    end;
  end;
  
  Result := count >= 3;
end;

