      requiredRooms += 1;
      i += 1;
      if requiredRooms > maxRooms then
        maxRooms := requiredRooms;
    end
    else
    begin
      requiredRooms -= 1;
      j += 1;
    end;
  end;
  
  Result := maxRooms;
end;

