  var maxSubstring := '';
  var currentSubstring := '';
  var prevChar := #0;
  var charCount := 0;
  
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    
    if ch = prevChar then
    begin
      charCount += 1;
      if charCount > 2 then
      begin
        if currentSubstring.Length > maxSubstring.Length then
          maxSubstring := currentSubstring;
        currentSubstring := new string(prevChar, 2);
        charCount := 1;
      end
      else
        currentSubstring += ch;
    end
    else
    begin
      if currentSubstring.Length > maxSubstring.Length then
        maxSubstring := currentSubstring;
      currentSubstring := ch.ToString;
      prevChar := ch;
      charCount := 1;
    end;
  end;
  
  if currentSubstring.Length > maxSubstring.Length then
    maxSubstring := currentSubstring;
  
  Result := maxSubstring;
end;

